	for _, line := range strings.Split(string(data), "\n") {
		if strings.HasPrefix(line, "--- PASS: ") || strings.HasPrefix(line, "--- SKIP: ") {
			fields := strings.Fields(line)
			if len(fields) >= 3 {
				seen[fields[2]] = true
			}
		}
	}
	for _, name := range names {
		if !seen[name] {
			t.Errorf("missing parent terminal: %s", name)
		}
	}
